-- Solo lectura. Seleccionar explícitamente la base correcta en phpMyAdmin.
SELECT DATABASE() AS esquema_actual, VERSION() AS version_servidor;
SELECT TABLE_NAME, ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('empresas','usuarios','compras_proveedores','flota_vehiculos','flota_cb2_placas_equivalencias') ORDER BY TABLE_NAME;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME IN ('empresas','usuarios','flota_vehiculos') AND COLUMN_NAME='id') OR (TABLE_NAME='compras_proveedores' AND COLUMN_NAME IN ('empresa_id','id'))) ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) AS columnas FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='compras_proveedores' GROUP BY INDEX_NAME,NON_UNIQUE;
-- Los tipos y signo de estos IDs deben ser INT compatibles con la migración.
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND ((TABLE_NAME IN ('empresas','usuarios','flota_vehiculos') AND COLUMN_NAME='id') OR (TABLE_NAME='compras_proveedores' AND COLUMN_NAME IN ('empresa_id','id'))) ORDER BY TABLE_NAME,COLUMN_NAME;
SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(CONCAT(COLUMN_NAME,IF(SUB_PART IS NULL,'',CONCAT('(',SUB_PART,')'))) ORDER BY SEQ_IN_INDEX) AS columnas FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('empresas','usuarios','compras_proveedores','flota_vehiculos') GROUP BY TABLE_NAME,INDEX_NAME,NON_UNIQUE ORDER BY TABLE_NAME,INDEX_NAME;
-- Los nombres de restricciones deben estar libres en el esquema antes de instalar.
SELECT TABLE_NAME,CONSTRAINT_NAME,CONSTRAINT_TYPE FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND CONSTRAINT_NAME IN ('fk_cb2placa_empresa','fk_cb2placa_proveedor','fk_cb2placa_vehiculo','fk_cb2placa_creado','fk_cb2placa_revocado','ck_cb2placa_revocacion');
